  slug text not null check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  language public.content_language not null default 'ar',
  title text not null,
  body_json jsonb,
  body_html text,
  status public.article_status not null default 'draft' check (status in ('draft', 'published')),
  show_in_footer boolean not null default false,
  position int not null default 0,
  page_kind text not null default 'standard'
    check (page_kind in ('standard', 'media_kit', 'contact', 'charter', 'privacy', 'about', 'legal')),
  seo_title text,
  seo_description text,
  translation_group_id uuid,
  updated_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (language, slug)
);

create trigger pages_set_updated_at
  before update on public.pages
  for each row execute function public.set_updated_at();

create table public.menu_items (
  id uuid primary key default gen_random_uuid(),
  menu text not null check (menu in ('header_extra', 'footer', 'utility')),
  label_ar text not null,
  label_fr text,
  target_type text not null check (target_type in ('url', 'category', 'page', 'tag')),
  url text check (url is null or url ~ '^(https://|/)'),
  category_id uuid references public.categories (id) on delete cascade,
  page_id uuid references public.pages (id) on delete cascade,
  tag_id uuid references public.tags (id) on delete cascade,
  parent_id uuid references public.menu_items (id) on delete cascade,
  position int not null default 0,
  is_active boolean not null default true,
  open_in_new_tab boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (
    (target_type = 'url' and url is not null)
    or (target_type = 'category' and category_id is not null)
    or (target_type = 'page' and page_id is not null)
    or (target_type = 'tag' and tag_id is not null)
  )
);
create index menu_items_menu_position_idx on public.menu_items (menu, position);

create trigger menu_items_set_updated_at
  before update on public.menu_items
  for each row execute function public.set_updated_at();

create table public.homepage_sections (
  id uuid primary key default gen_random_uuid(),
  locale text not null default 'both' check (locale in ('ar', 'fr', 'both')),
  type public.homepage_section_type not null,
  title_ar text,
  title_fr text,
  config jsonb not null default '{}'::jsonb,
  position int not null default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index homepage_sections_locale_position_idx on public.homepage_sections (locale, position);

create trigger homepage_sections_set_updated_at
  before update on public.homepage_sections
  for each row execute function public.set_updated_at();

create table public.redirects (
  from_path text primary key check (from_path ~ '^/'),
  to_path text not null check (to_path ~ '^/'),
  created_at timestamptz not null default now()
);

-- Keep old URLs alive when a slug changes (categories, tags, authors, pages).
create or replace function public.slug_redirect()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  prefix text := tg_argv[0];
  loc text;
begin
  if new.slug is distinct from old.slug then
    foreach loc in array (case when tg_table_name = 'pages' then array[to_jsonb(old) ->> 'language'] else array['ar', 'fr'] end) loop
      -- Point any redirect that targeted the old URL to the new one (no chains).
      update public.redirects set to_path = '/' || loc || prefix || new.slug
        where to_path = '/' || loc || prefix || old.slug;
      insert into public.redirects (from_path, to_path)
        values ('/' || loc || prefix || old.slug, '/' || loc || prefix || new.slug)
        on conflict (from_path) do update set to_path = excluded.to_path;
      delete from public.redirects where from_path = '/' || loc || prefix || new.slug;
    end loop;
  end if;
  return new;
end;
$$;

create trigger categories_slug_redirect after update of slug on public.categories
  for each row execute function public.slug_redirect('/section/');
create trigger tags_slug_redirect after update of slug on public.tags
  for each row execute function public.slug_redirect('/topic/');
create trigger profiles_slug_redirect after update of slug on public.profiles
  for each row execute function public.slug_redirect('/author/');
create trigger pages_slug_redirect after update of slug on public.pages
  for each row execute function public.slug_redirect('/p/');

-- ============================================================================
-- 20261001000800_settings.sql
-- ============================================================================
-- El Borj — 08 site settings, contact messages

create table public.site_settings (
  key text primary key check (key ~ '^[a-z0-9_]+$'),
  value jsonb not null,
  is_public boolean not null default false,
  updated_by uuid references public.profiles (id) on delete set null,
  updated_at timestamptz not null default now()
);

create or replace function public.site_settings_touch()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  if auth.uid() is not null then
    new.updated_by := auth.uid();
  end if;
  return new;
end;
$$;

create trigger site_settings_touch
  before insert or update on public.site_settings
  for each row execute function public.site_settings_touch();

-- Keys an editor must not change (integrations, ads, analytics, money).
create or replace function public.is_sensitive_setting(k text)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select k in ('adsense', 'ads_txt', 'ga4', 'analytics', 'consent', 'in_article_ads', 'media_kit');
$$;

-- Raw analytics retention can never drop below 35 days (monthly uniques need a full month).
create or replace function public.site_settings_validate()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.key = 'analytics' then
    new.value := jsonb_set(
      new.value, '{raw_retention_days}',
      to_jsonb(least(180, greatest(35, coalesce((new.value ->> 'raw_retention_days')::int, 60)))));
    new.value := jsonb_set(new.value, '{exclude_staff}', 'true'::jsonb);
    new.is_public := false;
  end if;
  return new;
end;
$$;

create trigger site_settings_validate
  before insert or update on public.site_settings
  for each row execute function public.site_settings_validate();

create table public.contact_messages (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(name) between 1 and 200),
  email text not null check (length(email) between 3 and 320),
  subject text not null check (subject in ('news_tip', 'advertising', 'correction', 'other')),
  message text not null check (length(message) between 1 and 8000),
  locale public.content_language not null default 'ar',
  status text not null default 'new' check (status in ('new', 'read', 'handled')),
  handled_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now()
);
create index contact_messages_status_idx on public.contact_messages (status, created_at desc);

-- ============================================================================
-- 20261001000900_ads.sql
-- ============================================================================
-- El Borj — 09 ad slots, direct sponsor campaigns, ad statistics

create table public.ad_slots (
  key text primary key check (key ~ '^[a-z0-9_]+$'),
  label_ar text not null,
  label_fr text,
  mode public.ad_mode not null default 'off',
  adsense_slot_id text check (adsense_slot_id is null or adsense_slot_id ~ '^[0-9]{4,20}$'),
  sizes jsonb not null default '{"desktop":[728,90],"mobile":[300,250]}'::jsonb,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger ad_slots_set_updated_at
  before update on public.ad_slots
  for each row execute function public.set_updated_at();

create table public.ad_campaigns (
  id uuid primary key default gen_random_uuid(),
  sponsor_name text not null check (length(btrim(sponsor_name)) > 0),
  slot_key text not null references public.ad_slots (key) on delete restrict,
  locale text not null default 'both' check (locale in ('ar', 'fr', 'both')),
  creative_desktop_media_id uuid references public.media (id) on delete restrict,
  creative_mobile_media_id uuid references public.media (id) on delete restrict,
  click_url text not null check (click_url ~ '^https://[^\s]+$'),
  alt_text text not null default '',
  starts_at timestamptz not null default now(),
  ends_at timestamptz,
  weight int not null default 1 check (weight between 1 and 100),
  category_ids uuid[],
  is_active boolean not null default true,
  notes text,
  created_by uuid references public.profiles (id) on delete set null default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (ends_at is null or ends_at > starts_at),
  check (creative_desktop_media_id is not null or creative_mobile_media_id is not null)
);
create index ad_campaigns_slot_idx on public.ad_campaigns (slot_key, is_active, starts_at, ends_at);

create trigger ad_campaigns_set_updated_at
  before update on public.ad_campaigns
  for each row execute function public.set_updated_at();

-- Written only by the server (service role) through record_ad_* below. Never editable.
create table public.ad_daily_stats (
  date date not null,
  campaign_id uuid not null references public.ad_campaigns (id) on delete cascade,
  impressions int not null default 0,
  clicks int not null default 0,
  primary key (date, campaign_id)
);

-- What the public site needs to render slots (no internal notes).
create view public.public_ad_slots as
  select key, label_ar, label_fr, mode, adsense_slot_id, sizes
  from public.ad_slots
  where is_active;

-- Currently running campaigns with render fields only (no click_url, no notes).
create view public.active_ad_campaigns as
  select c.id, c.sponsor_name, c.slot_key, c.locale, c.alt_text, c.weight, c.category_ids,
         c.starts_at, c.ends_at,
         md.storage_path as desktop_path, md.variants as desktop_variants, md.width as desktop_width, md.height as desktop_height,
         mm.storage_path as mobile_path, mm.variants as mobile_variants, mm.width as mobile_width, mm.height as mobile_height
  from public.ad_campaigns c
  join public.ad_slots s on s.key = c.slot_key and s.is_active
  left join public.media md on md.id = c.creative_desktop_media_id
  left join public.media mm on mm.id = c.creative_mobile_media_id
  where c.is_active and c.starts_at <= now() and (c.ends_at is null or c.ends_at > now());

-- Server-only counters. Only the service role may execute them (grants below).
create or replace function public.record_ad_impression(p_campaign_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.ad_daily_stats (date, campaign_id, impressions, clicks)
  select (now() at time zone 'Africa/Tunis')::date, c.id, 1, 0
  from public.ad_campaigns c where c.id = p_campaign_id
  on conflict (date, campaign_id) do update set impressions = public.ad_daily_stats.impressions + 1;
end;
$$;

create or replace function public.record_ad_click(p_campaign_id uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  target text;
begin
  select click_url into target from public.ad_campaigns where id = p_campaign_id;
  if target is null then
    return null;
  end if;
  insert into public.ad_daily_stats (date, campaign_id, impressions, clicks)
  values ((now() at time zone 'Africa/Tunis')::date, p_campaign_id, 0, 1)
  on conflict (date, campaign_id) do update set clicks = public.ad_daily_stats.clicks + 1;
  return target;
end;
$$;

revoke all on function public.record_ad_impression(uuid) from public, anon, authenticated;
revoke all on function public.record_ad_click(uuid) from public, anon, authenticated;
grant execute on function public.record_ad_impression(uuid) to service_role;
grant execute on function public.record_ad_click(uuid) to service_role;

-- Sponsor report (editor/admin), read-only.
create or replace function public.ad_campaign_report(p_campaign_id uuid)
returns table (date date, impressions int, clicks int)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_editor_or_admin() then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  return query
    select s.date, s.impressions, s.clicks from public.ad_daily_stats s
    where s.campaign_id = p_campaign_id order by s.date;
end;
$$;

-- ============================================================================
-- 20261001001000_analytics.sql
-- ============================================================================
-- El Borj — 10 first-party analytics: raw tables, salts, ingestion, rollups
--
-- Guarantee: no human can write these tables. anon/authenticated (every logged-in
-- role, admin included) get no INSERT/UPDATE/DELETE privilege and no write policy.
-- Only the service role (server routes) and SECURITY DEFINER cron functions write.

create table public.analytics_salts (
  month date primary key,
  salt bytea not null default extensions.gen_random_bytes(32)
);

create table public.pageviews_raw (
  pv_id uuid primary key,
  occurred_at timestamptz not null default now(),
  path text not null,
  article_id uuid references public.articles (id) on delete set null,
  category_id uuid references public.categories (id) on delete set null,
  locale public.content_language not null,
  source public.traffic_source not null default 'direct',
  referrer_host text,
  utm_source text,
  utm_medium text,
  utm_campaign text,
  country char(2) not null default 'XX',
  device public.device_type not null default 'other',
  visitor_hash bytea not null
);
create index pageviews_raw_occurred_idx on public.pageviews_raw (occurred_at);
create index pageviews_raw_article_idx on public.pageviews_raw (article_id, occurred_at);

create table public.engagement_raw (
  pv_id uuid primary key references public.pageviews_raw (pv_id) on delete cascade,
  engaged_seconds int not null default 0 check (engaged_seconds between 0 and 1800),
  max_scroll_pct smallint not null default 0 check (max_scroll_pct between 0 and 100),
  updated_at timestamptz not null default now()
);

create table public.analytics_daily (
  date date not null,
  dimension text not null check (dimension in ('site', 'locale', 'source', 'country', 'device', 'category', 'referrer_host', 'utm_campaign')),
  dimension_value text not null,
  pageviews int not null default 0,
  visitors int not null default 0,
  engaged_seconds_sum bigint not null default 0,
  engaged_count int not null default 0,
  reads int not null default 0,
  article_views int not null default 0,
  primary key (date, dimension, dimension_value)
);

create table public.analytics_daily_article (
  date date not null,
  article_id uuid not null references public.articles (id) on delete cascade,
  pageviews int not null default 0,
  visitors int not null default 0,
  engaged_seconds_sum bigint not null default 0,
  engaged_count int not null default 0,
  reads int not null default 0,
  source_breakdown jsonb not null default '{}'::jsonb,
  country_breakdown jsonb not null default '{}'::jsonb,
  device_breakdown jsonb not null default '{}'::jsonb,
  referrer_breakdown jsonb not null default '{}'::jsonb,
  primary key (date, article_id)
);
create index analytics_daily_article_article_idx on public.analytics_daily_article (article_id, date);

create table public.analytics_monthly_uniques (
  month date not null,
  dimension text not null check (dimension in ('site', 'category', 'author', 'locale')),
  dimension_value text not null,
  visitors int not null default 0,
  pageviews int not null default 0,
  primary key (month, dimension, dimension_value)
);

create table public.rollup_runs (
  id bigint generated always as identity primary key,
  job text not null,
  started_at timestamptz not null default now(),
  finished_at timestamptz,
  status text not null default 'running' check (status in ('running', 'ok', 'error')),
  detail text
);

-- Manual social numbers: the only human-entered statistics, always labeled as such.
create table public.social_stats (
  id uuid primary key default gen_random_uuid(),
  platform text not null check (platform in ('facebook', 'instagram', 'youtube', 'tiktok')),
  recorded_for date not null,
  followers int check (followers >= 0),
  reach_28d int check (reach_28d >= 0),
  engagement_28d int check (engagement_28d >= 0),
  note text,
  entered_by uuid references public.profiles (id) on delete set null default auth.uid(),
  created_at timestamptz not null default now()
);
create index social_stats_platform_idx on public.social_stats (platform, recorded_for desc);

-- ---------------------------------------------------------------------------
-- Salts (monthly, deleted after the next month so hashes can't be linked or reversed)

create or replace function public.ensure_salt(p_month date)
returns bytea
language plpgsql
security definer
set search_path = ''
as $$
declare
  m date := date_trunc('month', p_month)::date;
  s bytea;
begin
  select salt into s from public.analytics_salts where month = m;
  if s is null then
    insert into public.analytics_salts (month) values (m) on conflict (month) do nothing;
    select salt into s from public.analytics_salts where month = m;
  end if;
  return s;
end;
$$;

create or replace function public.rotate_salt()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  this_month date := date_trunc('month', now() at time zone 'Africa/Tunis')::date;
begin
  perform public.ensure_salt(this_month);
  perform public.ensure_salt((this_month + interval '1 month')::date);
  delete from public.analytics_salts where month < (this_month - interval '1 month')::date;
end;
$$;

-- ---------------------------------------------------------------------------
-- Ingestion (called by /api/t with the service role only). IP and user agent are
-- hashed together with the month's salt inside the database and never stored.

create or replace function public.track_pageview(
  p_pv_id uuid,
  p_path text,
  p_article_public_id bigint,
  p_category_slug text,
  p_locale public.content_language,
  p_source public.traffic_source,
  p_referrer_host text,
  p_utm_source text,
  p_utm_medium text,
  p_utm_campaign text,
  p_country text,
  p_device public.device_type,
  p_ip text,
  p_ua text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_salt bytea := public.ensure_salt((now() at time zone 'Africa/Tunis')::date);
  v_article uuid;
  v_category uuid;
begin
  if p_article_public_id is not null then
    select a.id, a.category_id into v_article, v_category
    from public.articles a
    where a.public_id = p_article_public_id and a.status = 'published' and a.published_at <= now();
    if v_article is null then
      return; -- unknown or unpublished article: don't count
    end if;
  elsif p_category_slug is not null then
    select c.id into v_category from public.categories c where c.slug = p_category_slug;
  end if;

  insert into public.pageviews_raw (
    pv_id, path, article_id, category_id, locale, source, referrer_host,
    utm_source, utm_medium, utm_campaign, country, device, visitor_hash
  ) values (
    p_pv_id, left(p_path, 300), v_article, v_category, p_locale, p_source, left(lower(p_referrer_host), 120),
    left(p_utm_source, 80), left(p_utm_medium, 80), left(p_utm_campaign, 120),
    upper(coalesce(nullif(left(p_country, 2), ''), 'XX')), p_device,
    extensions.digest(v_salt || convert_to(coalesce(p_ip, '') || '|' || coalesce(p_ua, '') || '|el-borj', 'UTF8'), 'sha256')
  )
  on conflict (pv_id) do nothing;
end;
$$;

create or replace function public.track_engagement(p_pv_id uuid, p_engaged_seconds int, p_max_scroll_pct int)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- Only for page views from the last 3 hours (no late tampering).
  if not exists (select 1 from public.pageviews_raw where pv_id = p_pv_id and occurred_at > now() - interval '3 hours') then
    return;
  end if;
  insert into public.engagement_raw (pv_id, engaged_seconds, max_scroll_pct)
  values (p_pv_id, least(1800, greatest(0, p_engaged_seconds)), least(100, greatest(0, p_max_scroll_pct)))
  on conflict (pv_id) do update set
    engaged_seconds = greatest(public.engagement_raw.engaged_seconds, excluded.engaged_seconds),
    max_scroll_pct = greatest(public.engagement_raw.max_scroll_pct, excluded.max_scroll_pct),
    updated_at = now();
end;
$$;

-- ---------------------------------------------------------------------------
-- Aggregation (shared by rollups and by live "today" numbers)

create or replace function public.tunis_day_start(d date)
returns timestamptz language sql immutable set search_path = ''
as $$ select (d::timestamp at time zone 'Africa/Tunis'); $$;

create or replace function public.tunis_today()
returns date language sql stable set search_path = ''
as $$ select (now() at time zone 'Africa/Tunis')::date; $$;

create or replace function public.analytics_aggregate(p_from timestamptz, p_to timestamptz)
returns table (
  dimension text, dimension_value text, pageviews bigint, visitors bigint,
  engaged_seconds_sum bigint, engaged_count bigint, reads bigint, article_views bigint
)
language sql
stable
security definer
set search_path = ''
as $$
  with base as (
    select p.*, e.engaged_seconds, e.max_scroll_pct
    from public.pageviews_raw p
    left join public.engagement_raw e on e.pv_id = p.pv_id
    where p.occurred_at >= p_from and p.occurred_at < p_to
  )
  select x.dim, x.val,
         count(*), count(distinct b.visitor_hash),
         coalesce(sum(b.engaged_seconds), 0)::bigint,
         count(b.engaged_seconds),
         count(*) filter (where b.article_id is not null and b.max_scroll_pct >= 75),
         count(*) filter (where b.article_id is not null)
  from base b
  cross join lateral (values
    ('site', 'all'),
    ('locale', b.locale::text),
    ('source', b.source::text),
    ('country', b.country::text),
    ('device', b.device::text),
    ('category', b.category_id::text),
    ('referrer_host', b.referrer_host),
    ('utm_campaign', b.utm_campaign)
  ) as x(dim, val)
  where x.val is not null
  group by x.dim, x.val;
$$;

create or replace function public.analytics_aggregate_articles(p_from timestamptz, p_to timestamptz)
returns table (
  article_id uuid, pageviews bigint, visitors bigint, engaged_seconds_sum bigint, engaged_count bigint,
  reads bigint, source_breakdown jsonb, country_breakdown jsonb, device_breakdown jsonb, referrer_breakdown jsonb
)
language sql
stable
security definer
set search_path = ''
as $$
  with base as (
    select p.*, e.engaged_seconds, e.max_scroll_pct
    from public.pageviews_raw p
    left join public.engagement_raw e on e.pv_id = p.pv_id
    where p.occurred_at >= p_from and p.occurred_at < p_to and p.article_id is not null
  )
  select b.article_id,
         count(*), count(distinct b.visitor_hash),
         coalesce(sum(b.engaged_seconds), 0)::bigint, count(b.engaged_seconds),
         count(*) filter (where b.max_scroll_pct >= 75),
         (select coalesce(jsonb_object_agg(s.source, s.n), '{}') from (select source::text as source, count(*) n from base b2 where b2.article_id = b.article_id group by 1) s),
         (select coalesce(jsonb_object_agg(s.country, s.n), '{}') from (select country::text as country, count(*) n from base b2 where b2.article_id = b.article_id group by 1 order by 2 desc limit 10) s),
         (select coalesce(jsonb_object_agg(s.device, s.n), '{}') from (select device::text as device, count(*) n from base b2 where b2.article_id = b.article_id group by 1) s),
         (select coalesce(jsonb_object_agg(s.host, s.n), '{}') from (select referrer_host as host, count(*) n from base b2 where b2.article_id = b.article_id and referrer_host is not null group by 1 order by 2 desc limit 10) s)
  from base b
  group by b.article_id;
$$;

-- Idempotent upsert of one Africa/Tunis day. Never deletes: once raw rows are pruned,
-- re-running an old day leaves the stored rollup untouched.
create or replace function public.rollup_day(p_day date)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  t0 timestamptz := public.tunis_day_start(p_day);
  t1 timestamptz := public.tunis_day_start(p_day + 1);
begin
  insert into public.analytics_daily as d (date, dimension, dimension_value, pageviews, visitors, engaged_seconds_sum, engaged_count, reads, article_views)
  select p_day, a.dimension, a.dimension_value, a.pageviews, a.visitors, a.engaged_seconds_sum, a.engaged_count, a.reads, a.article_views
  from public.analytics_aggregate(t0, t1) a
  on conflict (date, dimension, dimension_value) do update set
    pageviews = excluded.pageviews, visitors = excluded.visitors,
    engaged_seconds_sum = excluded.engaged_seconds_sum, engaged_count = excluded.engaged_count,
    reads = excluded.reads, article_views = excluded.article_views;

  insert into public.analytics_daily_article as d (date, article_id, pageviews, visitors, engaged_seconds_sum, engaged_count, reads,
                                                   source_breakdown, country_breakdown, device_breakdown, referrer_breakdown)
  select p_day, a.article_id, a.pageviews, a.visitors, a.engaged_seconds_sum, a.engaged_count, a.reads,
         a.source_breakdown, a.country_breakdown, a.device_breakdown, a.referrer_breakdown
  from public.analytics_aggregate_articles(t0, t1) a
  where exists (select 1 from public.articles x where x.id = a.article_id)
  on conflict (date, article_id) do update set
    pageviews = excluded.pageviews, visitors = excluded.visitors,
    engaged_seconds_sum = excluded.engaged_seconds_sum, engaged_count = excluded.engaged_count,
    reads = excluded.reads, source_breakdown = excluded.source_breakdown,
    country_breakdown = excluded.country_breakdown, device_breakdown = excluded.device_breakdown,
    referrer_breakdown = excluded.referrer_breakdown;
end;
$$;

-- Monthly unique visitors (site, category, author, locale) from raw rows.
create or replace function public.rollup_month_uniques(p_month date)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  m date := date_trunc('month', p_month)::date;
  t0 timestamptz := public.tunis_day_start(m);
  t1 timestamptz := public.tunis_day_start((m + interval '1 month')::date);
begin
  if not exists (select 1 from public.pageviews_raw where occurred_at >= t0 and occurred_at < t1) then
    return; -- nothing (left) to compute: keep any frozen numbers
  end if;
  insert into public.analytics_monthly_uniques as u (month, dimension, dimension_value, visitors, pageviews)
  select m, x.dim, x.val, count(distinct p.visitor_hash), count(*)
  from public.pageviews_raw p
  cross join lateral (values ('site', 'all'), ('locale', p.locale::text), ('category', p.category_id::text)) as x(dim, val)
  where p.occurred_at >= t0 and p.occurred_at < t1 and x.val is not null
  group by x.dim, x.val
  on conflict (month, dimension, dimension_value) do update set visitors = excluded.visitors, pageviews = excluded.pageviews;

  insert into public.analytics_monthly_uniques as u (month, dimension, dimension_value, visitors, pageviews)
  select m, 'author', aa.profile_id::text, count(distinct p.visitor_hash), count(*)
  from public.pageviews_raw p
  join public.article_authors aa on aa.article_id = p.article_id
  where p.occurred_at >= t0 and p.occurred_at < t1
  group by aa.profile_id
  on conflict (month, dimension, dimension_value) do update set visitors = excluded.visitors, pageviews = excluded.pageviews;
end;
$$;

create or replace function public.rollup_hourly()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  run_id bigint;
begin
  insert into public.rollup_runs (job) values ('rollup_hourly') returning id into run_id;
  perform public.rollup_day(public.tunis_today() - 1);
  perform public.rollup_day(public.tunis_today());
  update public.rollup_runs set finished_at = now(), status = 'ok' where id = run_id;
exception when others then
  update public.rollup_runs set finished_at = now(), status = 'error', detail = sqlerrm where id = run_id;
end;
$$;

create or replace function public.rollup_nightly()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  run_id bigint;
  retention int := coalesce((select (value ->> 'raw_retention_days')::int from public.site_settings where key = 'analytics'), 60);
  yesterday date := public.tunis_today() - 1;
  pruned bigint;
begin
  insert into public.rollup_runs (job) values ('rollup_nightly') returning id into run_id;
  retention := greatest(35, least(180, retention));
  perform public.rollup_day(yesterday);
  perform public.rollup_month_uniques(public.tunis_today());
  -- Freeze the previous month one last time on the first day of a new month.
  if date_trunc('month', yesterday) <> date_trunc('month', public.tunis_today()) then
    perform public.rollup_month_uniques(yesterday);
  end if;
  delete from public.pageviews_raw where occurred_at < now() - make_interval(days => retention);
  get diagnostics pruned = row_count;
  -- Keep the latest 30 revisions per article.
  delete from public.article_revisions r
  using (
    select id from (
      select id, row_number() over (partition by article_id order by created_at desc) rn
      from public.article_revisions
    ) x where x.rn > 30
  ) old
  where r.id = old.id;
  -- Handled contact messages older than 12 months.
  delete from public.contact_messages where status = 'handled' and created_at < now() - interval '12 months';
  update public.rollup_runs set finished_at = now(), status = 'ok', detail = 'pruned_raw=' || pruned where id = run_id;
  delete from public.rollup_runs where started_at < now() - interval '90 days';
exception when others then
  update public.rollup_runs set finished_at = now(), status = 'error', detail = sqlerrm where id = run_id;
end;
$$;

-- Admin recovery: re-run rollups for a date range (max 400 days).
create or replace function public.run_rollup(from_date date, to_date date)
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  d date;
  n int := 0;
  run_id bigint;
begin
  if not public.is_admin() then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  if to_date < from_date or to_date - from_date > 400 then
    raise exception 'invalid_range' using errcode = '22023';
  end if;
  insert into public.rollup_runs (job, detail) values ('run_rollup', from_date || '..' || to_date) returning id into run_id;
  d := from_date;
  while d <= to_date loop
    perform public.rollup_day(d);
    n := n + 1;
    d := d + 1;
  end loop;
  perform public.rollup_month_uniques(from_date);
  if date_trunc('month', to_date) <> date_trunc('month', from_date) then
    perform public.rollup_month_uniques(to_date);
  end if;
  update public.rollup_runs set finished_at = now(), status = 'ok' where id = run_id;
  return n;
end;
$$;

-- Lock down: ingestion and rollup internals are not callable by API users.
revoke all on function public.track_pageview(uuid, text, bigint, text, public.content_language, public.traffic_source, text, text, text, text, text, public.device_type, text, text) from public, anon, authenticated;
revoke all on function public.track_engagement(uuid, int, int) from public, anon, authenticated;
grant execute on function public.track_pageview(uuid, text, bigint, text, public.content_language, public.traffic_source, text, text, text, text, text, public.device_type, text, text) to service_role;
grant execute on function public.track_engagement(uuid, int, int) to service_role;
revoke all on function public.ensure_salt(date) from public, anon, authenticated;
revoke all on function public.rotate_salt() from public, anon, authenticated;
revoke all on function public.analytics_aggregate(timestamptz, timestamptz) from public, anon, authenticated;
revoke all on function public.analytics_aggregate_articles(timestamptz, timestamptz) from public, anon, authenticated;
revoke all on function public.rollup_day(date) from public, anon, authenticated;
revoke all on function public.rollup_month_uniques(date) from public, anon, authenticated;
revoke all on function public.rollup_hourly() from public, anon, authenticated;
revoke all on function public.rollup_nightly() from public, anon, authenticated;
grant execute on function public.ensure_salt(date), public.rotate_salt(), public.rollup_day(date),
  public.rollup_month_uniques(date), public.rollup_hourly(), public.rollup_nightly() to service_role;
revoke all on function public.run_rollup(date, date) from public, anon;
grant execute on function public.run_rollup(date, date) to authenticated;

-- ============================================================================
-- 20261001001100_analytics_stats.sql
-- ============================================================================
-- El Borj — 11 read-only statistics RPCs (dashboard, author stats, media kit)
-- Every function is SECURITY DEFINER and checks the caller's role itself.
-- "Today" is computed live from raw rows; earlier days come from rollups.

create or replace function public._stats_daily(p_from date, p_to date, p_dimension text)
returns table (
  date date, dimension_value text, pageviews bigint, visitors bigint,
  engaged_seconds_sum bigint, engaged_count bigint, reads bigint, article_views bigint
)
language sql
stable
security definer
set search_path = ''
as $$
  select d.date, d.dimension_value, d.pageviews::bigint, d.visitors::bigint, d.engaged_seconds_sum,
         d.engaged_count::bigint, d.reads::bigint, d.article_views::bigint
  from public.analytics_daily d
  where d.dimension = p_dimension and d.date between p_from and least(p_to, public.tunis_today() - 1)
  union all
  select public.tunis_today(), a.dimension_value, a.pageviews, a.visitors, a.engaged_seconds_sum,
         a.engaged_count, a.reads, a.article_views
  from public.analytics_aggregate(public.tunis_day_start(public.tunis_today()), public.tunis_day_start(public.tunis_today() + 1)) a
  where a.dimension = p_dimension and public.tunis_today() between p_from and p_to;
$$;

create or replace function public._stats_daily_article(p_from date, p_to date)
returns table (
  date date, article_id uuid, pageviews bigint, visitors bigint, engaged_seconds_sum bigint,
  engaged_count bigint, reads bigint, source_breakdown jsonb, country_breakdown jsonb,
  device_breakdown jsonb, referrer_breakdown jsonb
)
language sql
stable
security definer
set search_path = ''
as $$
  select d.date, d.article_id, d.pageviews::bigint, d.visitors::bigint, d.engaged_seconds_sum, d.engaged_count::bigint,
         d.reads::bigint, d.source_breakdown, d.country_breakdown, d.device_breakdown, d.referrer_breakdown
  from public.analytics_daily_article d
  where d.date between p_from and least(p_to, public.tunis_today() - 1)
  union all
  select public.tunis_today(), a.article_id, a.pageviews, a.visitors, a.engaged_seconds_sum, a.engaged_count, a.reads,
         a.source_breakdown, a.country_breakdown, a.device_breakdown, a.referrer_breakdown
  from public.analytics_aggregate_articles(public.tunis_day_start(public.tunis_today()), public.tunis_day_start(public.tunis_today() + 1)) a
  where public.tunis_today() between p_from and p_to;
$$;

-- Sum jsonb {key: n} objects.
create or replace function public._jsonb_sum(items jsonb[])
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select coalesce(jsonb_object_agg(k, n), '{}'::jsonb)
  from (
    select e.key as k, sum((e.value)::bigint) as n
    from unnest(items) as j(obj), jsonb_each_text(j.obj) as e
    group by e.key
    order by 2 desc
  ) s;
$$;

revoke all on function public._stats_daily(date, date, text) from public, anon, authenticated;
revoke all on function public._stats_daily_article(date, date) from public, anon, authenticated;

create or replace function public._require_editor()
returns void language plpgsql stable security definer set search_path = ''
as $$
begin
  if not public.is_editor_or_admin() then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
end;
$$;

create or replace function public._require_staff()
returns void language plpgsql stable security definer set search_path = ''
as $$
begin
  if not public.is_staff() then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
end;
$$;

-- ---------------------------------------------------------------------------

create or replace function public.stats_overview(p_from date, p_to date, p_locale text default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  dim text := case when p_locale is null then 'site' else 'locale' end;
  val text := coalesce(p_locale, 'all');
  r record;
  monthly int;
  is_month boolean := p_from = date_trunc('month', p_from)::date
                      and p_to = (date_trunc('month', p_from) + interval '1 month - 1 day')::date;
  published int;
begin
  perform public._require_editor();
  select coalesce(sum(s.pageviews), 0) pv, coalesce(sum(s.visitors), 0) vis,
         coalesce(sum(s.engaged_seconds_sum), 0) es, coalesce(sum(s.engaged_count), 0) ec,
         coalesce(sum(s.reads), 0) rd, coalesce(sum(s.article_views), 0) av
    into r
  from public._stats_daily(p_from, p_to, dim) s
  where s.dimension_value = val;

  if is_month then
    if date_trunc('month', p_from) = date_trunc('month', public.tunis_today()::timestamp) then
      select count(distinct p.visitor_hash) into monthly from public.pageviews_raw p
      where p.occurred_at >= public.tunis_day_start(p_from) and p.occurred_at < public.tunis_day_start(p_to + 1)
        and (p_locale is null or p.locale::text = p_locale);
    else
      select u.visitors into monthly from public.analytics_monthly_uniques u
      where u.month = p_from and u.dimension = dim and u.dimension_value = val;
    end if;
  end if;

  select count(*) into published from public.articles a
  where a.first_published_at >= public.tunis_day_start(p_from) and a.first_published_at < public.tunis_day_start(p_to + 1)
    and a.status = 'published' and (p_locale is null or a.language::text = p_locale);

  return jsonb_build_object(
    'pageviews', r.pv,
    'visitors_daily_sum', r.vis,
    'visitors_monthly', monthly,
    'single_day', p_from = p_to,
    'engaged_avg_seconds', case when r.ec > 0 then round(r.es::numeric / r.ec) else null end,
    'read_rate', case when r.av > 0 then round(r.rd::numeric / r.av, 4) else null end,
    'articles_published', published
  );
end;
$$;

create or replace function public.stats_timeseries(p_from date, p_to date, p_metric text default 'pageviews', p_granularity text default 'day')
returns table (bucket date, pageviews bigint, visitors bigint, engaged_avg_seconds numeric)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public._require_editor();
  if p_granularity not in ('day', 'week', 'month') then
    raise exception 'invalid_granularity' using errcode = '22023';
  end if;
  return query
    with days as (select generate_series(p_from, p_to, interval '1 day')::date as d),
    s as (select * from public._stats_daily(p_from, p_to, 'site'))
    select date_trunc(p_granularity, days.d)::date,
           coalesce(sum(s.pageviews), 0)::bigint, coalesce(sum(s.visitors), 0)::bigint,
           case when sum(s.engaged_count) > 0 then round(sum(s.engaged_seconds_sum)::numeric / sum(s.engaged_count)) end
    from days left join s on s.date = days.d
    group by 1 order by 1;
end;
$$;

create or replace function public.stats_top_articles(
  p_from date, p_to date, p_limit int default 10, p_category_id uuid default null, p_author_id uuid default null
)
returns table (
  article_id uuid, public_id bigint, title text, language public.content_language, published_at timestamptz,
  category_id uuid, author_names text, pageviews bigint, visitors bigint, engaged_avg_seconds numeric,
  read_rate numeric, main_source text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public._require_staff();
  if public.current_role_name() = 'author' then
    p_author_id := auth.uid();
  end if;
  return query
    with s as (
      select x.article_id, sum(x.pageviews) pv, sum(x.visitors) vis, sum(x.engaged_seconds_sum) es,
             sum(x.engaged_count) ec, sum(x.reads) rd, public._jsonb_sum(array_agg(x.source_breakdown)) src
      from public._stats_daily_article(p_from, p_to) x
      group by x.article_id
    )
    select a.id, a.public_id, a.title, a.language, a.published_at, a.category_id,
           (select string_agg(p.display_name_ar, '، ' order by aa.position) from public.article_authors aa
              join public.profiles p on p.id = aa.profile_id where aa.article_id = a.id),
           s.pv::bigint, s.vis::bigint,
           case when s.ec > 0 then round(s.es::numeric / s.ec) end,
           case when s.pv > 0 then round(s.rd::numeric / s.pv, 4) end,
           (select k from jsonb_each_text(s.src) as e(k, v) order by v::bigint desc limit 1)
    from s
    join public.articles a on a.id = s.article_id
    where (p_category_id is null or a.category_id = p_category_id
           or a.category_id in (select c.id from public.categories c where c.parent_id = p_category_id))
      and (p_author_id is null or exists (select 1 from public.article_authors aa where aa.article_id = a.id and aa.profile_id = p_author_id))
    order by s.pv desc
    limit least(greatest(p_limit, 1), 500);
end;
$$;

create or replace function public.stats_article_detail(p_article_id uuid, p_from date, p_to date)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  result jsonb;
begin
  perform public._require_staff();
  if not public.is_editor_or_admin() and not exists (
    select 1 from public.article_authors aa where aa.article_id = p_article_id and aa.profile_id = auth.uid()
  ) then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  with s as (select * from public._stats_daily_article(p_from, p_to) x where x.article_id = p_article_id)
  select jsonb_build_object(
    'daily', coalesce((select jsonb_agg(jsonb_build_object('date', d.d, 'pageviews', coalesce(s2.pageviews, 0), 'visitors', coalesce(s2.visitors, 0)) order by d.d)
                       from generate_series(p_from, p_to, interval '1 day') as d(d)
                       left join s s2 on s2.date = d.d::date), '[]'::jsonb),
    'pageviews', coalesce((select sum(pageviews) from s), 0),
    'visitors_daily_sum', coalesce((select sum(visitors) from s), 0),
    'engaged_avg_seconds', (select case when sum(engaged_count) > 0 then round(sum(engaged_seconds_sum)::numeric / sum(engaged_count)) end from s),
    'read_rate', (select case when sum(pageviews) > 0 then round(sum(reads)::numeric / sum(pageviews), 4) end from s),
    'sources', (select public._jsonb_sum(array_agg(source_breakdown)) from s),
    'countries', (select public._jsonb_sum(array_agg(country_breakdown)) from s),
    'devices', (select public._jsonb_sum(array_agg(device_breakdown)) from s),
    'referrers', (select public._jsonb_sum(array_agg(referrer_breakdown)) from s)
  ) into result;
  return result;
end;
$$;

create or replace function public.stats_breakdown(p_from date, p_to date, p_dimension text, p_limit int default 20)
returns table (value text, pageviews bigint, visitors bigint, share numeric)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public._require_editor();
  if p_dimension not in ('locale', 'source', 'country', 'device', 'category', 'referrer_host', 'utm_campaign') then
    raise exception 'invalid_dimension' using errcode = '22023';
  end if;
  return query
    with s as (
      select x.dimension_value v, sum(x.pageviews) pv, sum(x.visitors) vis
      from public._stats_daily(p_from, p_to, p_dimension) x group by 1
    ), total as (
      select coalesce(sum(x.pageviews), 0) t from public._stats_daily(p_from, p_to, 'site') x
    )
    select s.v, s.pv::bigint, s.vis::bigint, case when total.t > 0 then round(s.pv::numeric / total.t, 4) end
    from s, total
    order by s.pv desc
    limit least(greatest(p_limit, 1), 200);
end;
$$;

create or replace function public.stats_authors(p_from date, p_to date)
returns table (
  profile_id uuid, display_name_ar text, display_name_fr text, articles_published bigint,
  pageviews bigint, avg_views_per_article numeric, engaged_avg_seconds numeric
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  only_me uuid := case when public.current_role_name() = 'author' then auth.uid() end;
begin
  perform public._require_staff();
  return query
    with s as (
      select aa.profile_id pid, sum(x.pageviews) pv, sum(x.engaged_seconds_sum) es, sum(x.engaged_count) ec,
             count(distinct x.article_id) n_viewed
      from public._stats_daily_article(p_from, p_to) x
      join public.article_authors aa on aa.article_id = x.article_id
      group by aa.profile_id
    ), pub as (
      select aa.profile_id pid, count(*) n
      from public.articles a join public.article_authors aa on aa.article_id = a.id
      where a.status = 'published' and a.first_published_at >= public.tunis_day_start(p_from)
        and a.first_published_at < public.tunis_day_start(p_to + 1)
      group by aa.profile_id
    )
    select p.id, p.display_name_ar, p.display_name_fr, coalesce(pub.n, 0)::bigint, coalesce(s.pv, 0)::bigint,
           case when coalesce(s.n_viewed, 0) > 0 then round(s.pv::numeric / s.n_viewed, 1) end,
           case when coalesce(s.ec, 0) > 0 then round(s.es::numeric / s.ec) end
    from public.profiles p
    left join s on s.pid = p.id
    left join pub on pub.pid = p.id
    where (only_me is null or p.id = only_me) and (s.pid is not null or pub.pid is not null or p.id = only_me)
    order by coalesce(s.pv, 0) desc;
end;
$$;

create or replace function public.stats_categories(p_from date, p_to date)
returns table (
  category_id uuid, parent_id uuid, name_ar text, name_fr text, pageviews bigint,
  articles_published bigint, avg_views_per_article numeric
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public._require_editor();
  return query
    with s as (
      select x.dimension_value::uuid cid, sum(x.pageviews) pv
      from public._stats_daily(p_from, p_to, 'category') x group by 1
    ), pub as (
      select a.category_id cid, count(*) n from public.articles a
      where a.status = 'published' and a.first_published_at >= public.tunis_day_start(p_from)
        and a.first_published_at < public.tunis_day_start(p_to + 1)
      group by 1
    ), viewed as (
      select a.category_id cid, count(distinct x.article_id) n
      from public._stats_daily_article(p_from, p_to) x join public.articles a on a.id = x.article_id group by 1
    )
    select c.id, c.parent_id, c.name_ar, c.name_fr, coalesce(s.pv, 0)::bigint, coalesce(pub.n, 0)::bigint,
           case when coalesce(viewed.n, 0) > 0 then round(s.pv::numeric / viewed.n, 1) end
    from public.categories c
    left join s on s.cid = c.id
    left join pub on pub.cid = c.id
    left join viewed on viewed.cid = c.id
    order by coalesce(s.pv, 0) desc, c.position;
end;
$$;

create or replace function public.stats_realtime(p_minutes int default 30)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  since timestamptz := now() - make_interval(mins => least(greatest(p_minutes, 1), 1440));
begin
  perform public._require_editor();
  return jsonb_build_object(
    'pageviews', (select count(*) from public.pageviews_raw where occurred_at >= since),
    'top', coalesce((
      select jsonb_agg(t) from (
        select a.id as article_id, a.public_id, a.title, a.language, count(*) as pageviews
        from public.pageviews_raw p join public.articles a on a.id = p.article_id
        where p.occurred_at >= since
        group by a.id order by count(*) desc limit 5
      ) t), '[]'::jsonb)
  );
end;
$$;

-- Author self-service ("my stats").
create or replace function public.my_summary(p_from date, p_to date)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  r record;
begin
  perform public._require_staff();
  select coalesce(sum(x.pageviews), 0) pv, coalesce(sum(x.visitors), 0) vis,
         coalesce(sum(x.engaged_seconds_sum), 0) es, coalesce(sum(x.engaged_count), 0) ec,
         coalesce(sum(x.reads), 0) rd
    into r
  from public._stats_daily_article(p_from, p_to) x
  where exists (select 1 from public.article_authors aa where aa.article_id = x.article_id and aa.profile_id = auth.uid());
  return jsonb_build_object(
    'pageviews', r.pv, 'visitors_daily_sum', r.vis,
    'engaged_avg_seconds', case when r.ec > 0 then round(r.es::numeric / r.ec) end,
    'read_rate', case when r.pv > 0 then round(r.rd::numeric / r.pv, 4) end,
    'articles_published', (select count(*) from public.articles a join public.article_authors aa on aa.article_id = a.id
                           where aa.profile_id = auth.uid() and a.status = 'published'
                             and a.first_published_at >= public.tunis_day_start(p_from)
                             and a.first_published_at < public.tunis_day_start(p_to + 1))
  );
end;
$$;

create or replace function public.my_article_stats(p_from date, p_to date)
returns table (
  article_id uuid, public_id bigint, title text, language public.content_language, published_at timestamptz,
  category_id uuid, author_names text, pageviews bigint, visitors bigint, engaged_avg_seconds numeric,
  read_rate numeric, main_source text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public._require_staff();
  return query select * from public.stats_top_articles(p_from, p_to, 500, null, auth.uid());
end;
$$;

-- Public "most read" ranking (ids only, no numbers). Falls back to nothing when
-- there is no data yet; the site then shows the latest articles.
create or replace function public.public_most_read(
  p_window_days int default 7, p_limit int default 5, p_category_id uuid default null, p_language public.content_language default null
)
returns table (article_id uuid)
language sql
stable
security definer
set search_path = ''
as $$
  select x.article_id
  from public._stats_daily_article(public.tunis_today() - least(greatest(p_window_days, 1), 90), public.tunis_today()) x
  join public.articles a on a.id = x.article_id
  where a.status = 'published' and a.published_at <= now()
    and (p_language is null or a.language = p_language)
    and (p_category_id is null or a.category_id = p_category_id
         or a.category_id in (select c.id from public.categories c where c.parent_id = p_category_id))
  group by x.article_id
  order by sum(x.pageviews) desc
  limit least(greatest(p_limit, 1), 20);
$$;

-- Round DOWN to two significant digits (12,345 -> 12,000). Never rounds up.
create or replace function public.round_down_2sig(n numeric)
returns bigint
language sql
immutable
set search_path = ''
as $$
  select (case
    when n is null then null
    when n < 100 then floor(n)
    else floor(n / power(10::numeric, floor(log(n)) - 1)) * power(10::numeric, floor(log(n)) - 1)
  end)::bigint;
$$;

-- The only public statistics function. Returns only the metrics enabled in
-- site_settings.media_kit, for the configured period, rounded down if configured.
create or replace function public.media_kit_public()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  cfg jsonb := coalesce((select value from public.site_settings where key = 'media_kit'), '{}'::jsonb);
  metrics jsonb := coalesce(cfg -> 'metrics', '{}'::jsonb);
  period text := coalesce(cfg ->> 'period', 'last_full_month');
  rnd boolean := coalesce(cfg ->> 'rounding', 'exact') = 'round_down';
  today date := public.tunis_today();
  p_from date;
  p_to date;
  months int := 1;
  pv numeric;
  vis numeric;
  es numeric;
  ec numeric;
  total numeric;
  out jsonb := '{}'::jsonb;
  fb record;
begin
  if period = 'last_30_days' then
    p_from := today - 30; p_to := today - 1;
  elsif period = 'last_3_months_avg' then
    p_from := (date_trunc('month', today) - interval '3 months')::date;
    p_to := (date_trunc('month', today) - interval '1 day')::date;
    months := 3;
  else
    period := 'last_full_month';
    p_from := (date_trunc('month', today) - interval '1 month')::date;
    p_to := (date_trunc('month', today) - interval '1 day')::date;
  end if;

  select coalesce(sum(d.pageviews), 0), coalesce(sum(d.engaged_seconds_sum), 0), coalesce(sum(d.engaged_count), 0)
    into pv, es, ec
  from public.analytics_daily d where d.dimension = 'site' and d.date between p_from and p_to;
  total := pv;

  if period = 'last_30_days' then
    select count(distinct p.visitor_hash) into vis from public.pageviews_raw p
    where p.occurred_at >= public.tunis_day_start(p_from) and p.occurred_at < public.tunis_day_start(p_to + 1);
  else
    select coalesce(avg(u.visitors), 0) into vis from public.analytics_monthly_uniques u
    where u.dimension = 'site' and u.month between p_from and p_to;
  end if;

  out := jsonb_build_object('period', period, 'from', p_from, 'to', p_to, 'rounded', rnd);

  if coalesce((metrics ->> 'monthly_pageviews')::boolean, false) then
    out := out || jsonb_build_object('monthly_pageviews',
      case when rnd then public.round_down_2sig(floor(pv / months)) else floor(pv / months)::bigint end);
  end if;
  if coalesce((metrics ->> 'monthly_visitors')::boolean, false) then
    out := out || jsonb_build_object('monthly_visitors',
      case when rnd then public.round_down_2sig(floor(vis)) else floor(vis)::bigint end);
  end if;
  if coalesce((metrics ->> 'engaged_time')::boolean, false) then
    out := out || jsonb_build_object('engaged_avg_seconds', case when ec > 0 then floor(es / ec) end);
  end if;
  if coalesce((metrics ->> 'mobile_share')::boolean, false) then
    out := out || jsonb_build_object('mobile_share', (
      select case when total > 0 then floor(coalesce(sum(d.pageviews), 0) * 100 / total) end
      from public.analytics_daily d
      where d.dimension = 'device' and d.dimension_value = 'mobile' and d.date between p_from and p_to));
  end if;
  if coalesce((metrics ->> 'geo')::boolean, false) then
    out := out || jsonb_build_object('geo', (
      select jsonb_build_object(
        'tunisia_share', case when total > 0 then floor(coalesce(sum(t.pv) filter (where t.c = 'TN'), 0) * 100 / total) end,
        'abroad_share', case when total > 0 then floor(coalesce(sum(t.pv) filter (where t.c <> 'TN'), 0) * 100 / total) end,
        'top_countries', coalesce((
          select jsonb_agg(jsonb_build_object('country', x.c, 'share', floor(x.pv * 100 / total)) order by x.pv desc)
          from (select d.dimension_value c, sum(d.pageviews) pv from public.analytics_daily d
                where d.dimension = 'country' and d.date between p_from and p_to and d.dimension_value not in ('XX')
                group by 1 order by 2 desc limit 3) x
          where total > 0), '[]'::jsonb))
      from (select d.dimension_value c, sum(d.pageviews) pv from public.analytics_daily d
            where d.dimension = 'country' and d.date between p_from and p_to group by 1) t));
  end if;
  if coalesce((metrics ->> 'top_sections')::boolean, false) then
    out := out || jsonb_build_object('top_sections', coalesce((
      select jsonb_agg(jsonb_build_object('slug', c.slug, 'name_ar', c.name_ar, 'name_fr', c.name_fr) order by x.pv desc)
      from (select d.dimension_value::uuid cid, sum(d.pageviews) pv from public.analytics_daily d
            where d.dimension = 'category' and d.date between p_from and p_to group by 1 order by 2 desc limit 5) x
      join public.categories c on c.id = x.cid and c.is_active), '[]'::jsonb));
  end if;
  if coalesce((metrics ->> 'articles_per_month')::boolean, false) then
    out := out || jsonb_build_object('articles_per_month', (
      select floor(count(*)::numeric / months) from public.articles a
      where a.status = 'published' and a.first_published_at >= public.tunis_day_start(p_from)
        and a.first_published_at < public.tunis_day_start(p_to + 1)));
  end if;
  if coalesce((metrics ->> 'facebook_followers')::boolean, false) then
    select s.followers, s.reach_28d, s.recorded_for into fb from public.social_stats s
    where s.platform = 'facebook' and s.followers is not null order by s.recorded_for desc, s.created_at desc limit 1;
    if found then
      out := out || jsonb_build_object('facebook', jsonb_build_object(
        'followers', case when rnd then public.round_down_2sig(fb.followers) else fb.followers end,
        'reach_28d', case when rnd then public.round_down_2sig(fb.reach_28d) else fb.reach_28d end,
        'recorded_for', fb.recorded_for, 'manual', true));
    end if;
  end if;
  return out;
end;
$$;

-- Admin "system" page.
create or replace function public.admin_system_status()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_admin() then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'db_size_bytes', pg_database_size(current_database()),
    'storage_bytes', (select coalesce(sum((metadata ->> 'size')::bigint), 0) from storage.objects),
    'raw_pageviews', (select count(*) from public.pageviews_raw),
    'raw_engagement', (select count(*) from public.engagement_raw),
    'last_rollups', coalesce((select jsonb_agg(r order by r.started_at desc) from (
        select job, started_at, finished_at, status, detail from public.rollup_runs order by started_at desc limit 10) r), '[]'::jsonb),
    'cron_jobs', coalesce((select jsonb_agg(jsonb_build_object('name', j.jobname, 'schedule', j.schedule, 'active', j.active))
                           from cron.job j), '[]'::jsonb)
  );
end;
$$;

revoke all on function public._jsonb_sum(jsonb[]) from anon;
revoke all on function public.stats_overview(date, date, text) from public, anon;
revoke all on function public.stats_timeseries(date, date, text, text) from public, anon;
revoke all on function public.stats_top_articles(date, date, int, uuid, uuid) from public, anon;
revoke all on function public.stats_article_detail(uuid, date, date) from public, anon;
revoke all on function public.stats_breakdown(date, date, text, int) from public, anon;
revoke all on function public.stats_authors(date, date) from public, anon;
revoke all on function public.stats_categories(date, date) from public, anon;
