-- ============================================================================
-- 20261001001200_search.sql
-- ============================================================================
-- El Borj — 12 search
-- Full text on normalize_ar()'d title/subtitle/body ('simple' config), with a
-- trigram fallback on the title for short or misspelled queries.

create or replace function public.search_articles(
  q text,
  lang public.content_language default null,
  "limit" int default 20,
  "offset" int default 0,
  category uuid default null,
  since timestamptz default null
)
returns table (id uuid, public_id bigint, rank real, total bigint)
language sql
stable
security invoker
set search_path = ''
as $$
  with nq as (
    select public.normalize_ar(btrim(coalesce(q, ''))) as t
  ), terms as (
    select string_agg(quote_literal(w) || ':*', ' & ') as tsq
    from nq, regexp_split_to_table(regexp_replace(nq.t, '[''"&|!():*<>\\,.؛،؟?«»]+', ' ', 'g'), '\s+') as w
    where length(w) > 0
  ), matches as (
    select a.id, a.public_id,
           greatest(
             case when terms.tsq is not null then ts_rank(a.search_vector, to_tsquery('simple', terms.tsq)) else 0 end,
             extensions.similarity(public.normalize_ar(a.title), nq.t) * 0.5
           )::real as rank,
           a.published_at
    from public.articles a, nq, terms
    where a.status = 'published' and a.published_at <= now()
      and length(nq.t) > 0
      and (lang is null or a.language = lang)
      and (category is null or a.category_id = category
           or a.category_id in (select c.id from public.categories c where c.parent_id = category))
      and (since is null or a.published_at >= since)
      and (
        (terms.tsq is not null and a.search_vector @@ to_tsquery('simple', terms.tsq))
        or extensions.similarity(public.normalize_ar(a.title), nq.t) > 0.3
        or (length(nq.t) >= 3 and public.normalize_ar(a.title) like '%' || nq.t || '%')
      )
  )
  select m.id, m.public_id, m.rank, count(*) over ()
  from matches m
  order by m.rank desc, m.published_at desc
  limit least(greatest("limit", 1), 50) offset greatest("offset", 0);
$$;

grant execute on function public.search_articles(text, public.content_language, int, int, uuid, timestamptz) to anon, authenticated;

-- ============================================================================
-- 20261001001300_editorial_rpcs.sql
-- ============================================================================
-- El Borj — 13 editorial helpers used by the admin (all SECURITY INVOKER: RLS applies)

-- Move every article of a category to another one, then delete it (one transaction).
create or replace function public.delete_category_with_move(p_category_id uuid, p_target_id uuid default null)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if not public.is_editor_or_admin() then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  if exists (select 1 from public.categories where parent_id = p_category_id) then
    raise exception 'has_children: move or delete the sub-sections first' using errcode = '23503';
  end if;
  if p_target_id is not null then
    if p_target_id = p_category_id then
      raise exception 'invalid_target' using errcode = '22023';
    end if;
    update public.articles set category_id = p_target_id where category_id = p_category_id;
    insert into public.article_categories (article_id, category_id)
      select article_id, p_target_id from public.article_categories where category_id = p_category_id
      on conflict do nothing;
    update public.homepage_sections set config = jsonb_set(config, '{category_id}', to_jsonb(p_target_id::text))
      where config ->> 'category_id' = p_category_id::text;
  end if;
  delete from public.article_categories where category_id = p_category_id;
  delete from public.categories where id = p_category_id;
end;
$$;

-- Reorder siblings: ids in their new order.
create or replace function public.reorder_categories(p_ids uuid[])
returns void
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if not public.is_editor_or_admin() then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  update public.categories c set position = o.ord
  from unnest(p_ids) with ordinality as o(id, ord)
  where c.id = o.id;
end;
$$;

create or replace function public.reorder_rows(p_table text, p_ids uuid[])
returns void
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if not public.is_editor_or_admin() then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  if p_table not in ('categories', 'article_formats', 'homepage_sections', 'menu_items', 'pages') then
    raise exception 'invalid_table' using errcode = '22023';
  end if;
  execute format(
    'update public.%I t set position = o.ord from unnest($1) with ordinality as o(id, ord) where t.id = o.id',
    p_table) using p_ids;
end;
$$;

-- Merge tag "from" into tag "into": moves links, adds a redirect, deletes "from".
create or replace function public.merge_tags(p_from uuid, p_into uuid)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  from_slug text;
  into_slug text;
begin
  if not public.is_editor_or_admin() then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  if p_from = p_into then
    raise exception 'invalid_target' using errcode = '22023';
  end if;
  select slug into from_slug from public.tags where id = p_from;
  select slug into into_slug from public.tags where id = p_into;
  if from_slug is null or into_slug is null then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
  insert into public.article_tags (article_id, tag_id)
    select article_id, p_into from public.article_tags where tag_id = p_from
    on conflict do nothing;
  delete from public.article_tags where tag_id = p_from;
  insert into public.redirects (from_path, to_path) values
    ('/ar/topic/' || from_slug, '/ar/topic/' || into_slug),
    ('/fr/topic/' || from_slug, '/fr/topic/' || into_slug)
  on conflict (from_path) do update set to_path = excluded.to_path;
  delete from public.tags where id = p_from;
end;
$$;

-- Where is an image used? (delete is blocked while it is used)
create or replace function public.media_usage(p_media_id uuid)
returns table (kind text, ref_id uuid, label text)
language sql
stable
security invoker
set search_path = ''
as $$
  select 'article_cover', a.id, a.title from public.articles a where a.cover_media_id = p_media_id or a.og_media_id = p_media_id
  union all
  select 'article_body', a.id, a.title from public.articles a where a.body_json::text like '%' || p_media_id::text || '%'
  union all
  select 'page_body', p.id, p.title from public.pages p where p.body_json::text like '%' || p_media_id::text || '%'
  union all
  select 'profile', p.id, p.display_name_ar from public.profiles p where p.avatar_media_id = p_media_id
  union all
  select 'tag', t.id, t.name_ar from public.tags t where t.image_media_id = p_media_id
  union all
  select 'ad_campaign', c.id, c.sponsor_name from public.ad_campaigns c
    where c.creative_desktop_media_id = p_media_id or c.creative_mobile_media_id = p_media_id
  union all
  select 'setting', null::uuid, s.key from public.site_settings s where s.value::text like '%' || p_media_id::text || '%';
$$;

-- Category article counts (incl. drafts) for the admin tree.
create or replace function public.category_article_counts()
returns table (category_id uuid, n bigint)
language sql
stable
security invoker
set search_path = ''
as $$
  select category_id, count(*) from public.articles group by category_id;
$$;

revoke all on function public.delete_category_with_move(uuid, uuid), public.reorder_categories(uuid[]),
  public.reorder_rows(text, uuid[]), public.merge_tags(uuid, uuid), public.media_usage(uuid),
  public.category_article_counts() from public, anon;
grant execute on function public.delete_category_with_move(uuid, uuid), public.reorder_categories(uuid[]),
  public.reorder_rows(text, uuid[]), public.merge_tags(uuid, uuid), public.media_usage(uuid),
  public.category_article_counts() to authenticated;

-- ============================================================================
-- 20261001001400_rls_policies.sql
-- ============================================================================
-- El Borj — 14 row level security
-- Roles: anon (public site), authenticated (+ profiles.role: author/editor/admin),
-- service_role (server only: analytics ingestion, ad counters, invites).

-- Enable RLS everywhere.
alter table public.profiles enable row level security;
alter table public.categories enable row level security;
alter table public.article_formats enable row level security;
alter table public.tags enable row level security;
alter table public.media enable row level security;
alter table public.articles enable row level security;
alter table public.article_authors enable row level security;
alter table public.article_categories enable row level security;
alter table public.article_tags enable row level security;
alter table public.article_revisions enable row level security;
alter table public.pages enable row level security;
alter table public.menu_items enable row level security;
alter table public.homepage_sections enable row level security;
alter table public.redirects enable row level security;
alter table public.site_settings enable row level security;
alter table public.contact_messages enable row level security;
alter table public.ad_slots enable row level security;
alter table public.ad_campaigns enable row level security;
alter table public.ad_daily_stats enable row level security;
alter table public.analytics_salts enable row level security;
alter table public.pageviews_raw enable row level security;
alter table public.engagement_raw enable row level security;
alter table public.analytics_daily enable row level security;
alter table public.analytics_daily_article enable row level security;
alter table public.analytics_monthly_uniques enable row level security;
alter table public.rollup_runs enable row level security;
alter table public.social_stats enable row level security;

-- ---------------------------------------------------------------------------
-- Statistics can't be written by any human. Remove the privileges themselves
-- (not only the policies) from every API role, admins included.
revoke all on public.analytics_salts, public.pageviews_raw, public.engagement_raw from anon, authenticated;
revoke insert, update, delete, truncate on public.analytics_daily, public.analytics_daily_article,
  public.analytics_monthly_uniques, public.rollup_runs, public.ad_daily_stats from anon, authenticated;
revoke all on public.analytics_daily, public.analytics_daily_article, public.analytics_monthly_uniques,
  public.rollup_runs, public.ad_daily_stats from anon;

-- Read-only views for the public site. Simple views are auto-updatable, so remove
-- write privileges explicitly.
revoke all on public.public_authors, public.public_ad_slots, public.active_ad_campaigns from anon, authenticated;
grant select on public.public_authors, public.public_ad_slots, public.active_ad_campaigns to anon, authenticated;

-- ---------------------------------------------------------------------------
-- profiles (anon uses the public_authors view)
create policy profiles_select_staff on public.profiles for select to authenticated
  using (public.is_staff() or id = auth.uid());
create policy profiles_update_self on public.profiles for update to authenticated
  using (id = auth.uid()) with check (id = auth.uid());
create policy profiles_admin_all on public.profiles for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- categories / formats / tags
create policy categories_select on public.categories for select to anon, authenticated
  using (is_active or public.is_staff());
create policy categories_write on public.categories for all to authenticated
  using (public.is_editor_or_admin()) with check (public.is_editor_or_admin());

create policy formats_select on public.article_formats for select to anon, authenticated
  using (is_active or public.is_staff());
create policy formats_write on public.article_formats for all to authenticated
  using (public.is_editor_or_admin()) with check (public.is_editor_or_admin());

create policy tags_select on public.tags for select to anon, authenticated using (true);
create policy tags_write on public.tags for all to authenticated
  using (public.is_editor_or_admin()) with check (public.is_editor_or_admin());
-- Authors can create new tags from the editor (typeahead "create new").
create policy tags_author_insert on public.tags for insert to authenticated
  with check (public.is_staff());

-- media
create policy media_select on public.media for select to anon, authenticated using (true);
create policy media_insert on public.media for insert to authenticated
  with check (public.is_editor_or_admin() or (public.is_staff() and uploaded_by = auth.uid()));
create policy media_update on public.media for update to authenticated
  using (public.is_editor_or_admin() or (public.is_staff() and uploaded_by = auth.uid()))
  with check (public.is_editor_or_admin() or (public.is_staff() and uploaded_by = auth.uid()));
create policy media_delete on public.media for delete to authenticated
  using (public.is_editor_or_admin() or (public.is_staff() and uploaded_by = auth.uid()));

-- articles
create policy articles_select on public.articles for select to anon, authenticated
  using (
    (status = 'published' and published_at <= now())
    or public.is_editor_or_admin()
    or (public.is_staff() and public.is_article_author(id))
  );
create policy articles_insert on public.articles for insert to authenticated
  with check (
    public.is_editor_or_admin()
    or (public.current_role_name() = 'author' and created_by = auth.uid() and status in ('draft', 'in_review'))
  );
create policy articles_update_editor on public.articles for update to authenticated
  using (public.is_editor_or_admin()) with check (public.is_editor_or_admin());
create policy articles_update_author on public.articles for update to authenticated
  using (public.current_role_name() = 'author' and public.is_article_author(id) and status in ('draft', 'in_review'))
  with check (public.current_role_name() = 'author' and status in ('draft', 'in_review'));
create policy articles_delete_admin on public.articles for delete to authenticated
  using (public.is_admin());
create policy articles_delete_editor_drafts on public.articles for delete to authenticated
  using (public.current_role_name() = 'editor' and status = 'draft');

-- article join tables
create policy article_authors_select on public.article_authors for select to anon, authenticated
  using (public.is_article_public(article_id) or public.is_editor_or_admin() or public.is_article_author(article_id));
create policy article_authors_write on public.article_authors for all to authenticated
  using (public.can_edit_article(article_id)) with check (public.can_edit_article(article_id));

create policy article_categories_select on public.article_categories for select to anon, authenticated
  using (public.is_article_public(article_id) or public.is_editor_or_admin() or public.is_article_author(article_id));
create policy article_categories_write on public.article_categories for all to authenticated
  using (public.can_edit_article(article_id)) with check (public.can_edit_article(article_id));

create policy article_tags_select on public.article_tags for select to anon, authenticated
  using (public.is_article_public(article_id) or public.is_editor_or_admin() or public.is_article_author(article_id));
create policy article_tags_write on public.article_tags for all to authenticated
  using (public.can_edit_article(article_id)) with check (public.can_edit_article(article_id));

create policy article_revisions_select on public.article_revisions for select to authenticated
  using (public.is_editor_or_admin() or public.is_article_author(article_id));
create policy article_revisions_insert on public.article_revisions for insert to authenticated
  with check (public.can_edit_article(article_id));
create policy article_revisions_delete on public.article_revisions for delete to authenticated
  using (public.is_admin());

-- pages, menus, homepage, redirects
create policy pages_select on public.pages for select to anon, authenticated
  using (status = 'published' or public.is_staff());
create policy pages_write on public.pages for all to authenticated
  using (public.is_editor_or_admin()) with check (public.is_editor_or_admin());

create policy menu_items_select on public.menu_items for select to anon, authenticated
  using (is_active or public.is_staff());
create policy menu_items_write on public.menu_items for all to authenticated
  using (public.is_editor_or_admin()) with check (public.is_editor_or_admin());

create policy homepage_sections_select on public.homepage_sections for select to anon, authenticated
  using (is_active or public.is_staff());
create policy homepage_sections_write on public.homepage_sections for all to authenticated
  using (public.is_editor_or_admin()) with check (public.is_editor_or_admin());

create policy redirects_select on public.redirects for select to anon, authenticated using (true);
create policy redirects_write on public.redirects for all to authenticated
  using (public.is_editor_or_admin()) with check (public.is_editor_or_admin());

-- settings
create policy site_settings_select on public.site_settings for select to anon, authenticated
  using (is_public or public.is_editor_or_admin());
create policy site_settings_insert on public.site_settings for insert to authenticated
  with check (public.is_admin() or (public.is_editor_or_admin() and not public.is_sensitive_setting(key)));
create policy site_settings_update on public.site_settings for update to authenticated
  using (public.is_admin() or (public.is_editor_or_admin() and not public.is_sensitive_setting(key)))
  with check (public.is_admin() or (public.is_editor_or_admin() and not public.is_sensitive_setting(key)));
create policy site_settings_delete on public.site_settings for delete to authenticated
  using (public.is_admin());

-- contact messages: inserted by the server (service role) only
create policy contact_messages_staff on public.contact_messages for select to authenticated
  using (public.is_editor_or_admin());
create policy contact_messages_update on public.contact_messages for update to authenticated
  using (public.is_editor_or_admin()) with check (public.is_editor_or_admin());
create policy contact_messages_delete on public.contact_messages for delete to authenticated
  using (public.is_editor_or_admin());
revoke insert on public.contact_messages from anon, authenticated;

-- ads
create policy ad_slots_select on public.ad_slots for select to authenticated
  using (public.is_editor_or_admin());
create policy ad_slots_admin on public.ad_slots for all to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy ad_campaigns_select on public.ad_campaigns for select to authenticated
  using (public.is_editor_or_admin());
create policy ad_campaigns_admin on public.ad_campaigns for all to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy ad_daily_stats_select on public.ad_daily_stats for select to authenticated
  using (public.is_editor_or_admin());

-- analytics rollups: read-only for editors/admins (authors go through RPCs)
create policy analytics_daily_select on public.analytics_daily for select to authenticated
  using (public.is_editor_or_admin());
create policy analytics_daily_article_select on public.analytics_daily_article for select to authenticated
  using (public.is_editor_or_admin());
create policy analytics_monthly_uniques_select on public.analytics_monthly_uniques for select to authenticated
  using (public.is_editor_or_admin());
create policy rollup_runs_select on public.rollup_runs for select to authenticated
  using (public.is_admin());

-- manual social stats (human data, labeled as such everywhere)
create policy social_stats_select on public.social_stats for select to authenticated
  using (public.is_editor_or_admin());
create policy social_stats_insert on public.social_stats for insert to authenticated
  with check (public.is_editor_or_admin() and entered_by = auth.uid());
create policy social_stats_update_own on public.social_stats for update to authenticated
  using (public.is_admin() or (public.is_editor_or_admin() and entered_by = auth.uid() and created_at > now() - interval '24 hours'))
  with check (public.is_admin() or (public.is_editor_or_admin() and entered_by = auth.uid()));
create policy social_stats_delete on public.social_stats for delete to authenticated
  using (public.is_admin());

-- ============================================================================
-- 20261001001500_storage.sql
-- ============================================================================
-- El Borj — 15 storage bucket "media" (public read, images only, 10 MB max)

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('media', 'media', true, 10485760, array['image/jpeg', 'image/png', 'image/webp', 'image/avif', 'image/svg+xml'])
on conflict (id) do update set
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

create policy media_objects_read on storage.objects for select to anon, authenticated
  using (bucket_id = 'media');

create policy media_objects_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'media' and public.is_staff());

create policy media_objects_update on storage.objects for update to authenticated
  using (bucket_id = 'media' and (public.is_editor_or_admin() or owner_id = (select auth.uid())::text))
  with check (bucket_id = 'media' and public.is_staff());

create policy media_objects_delete on storage.objects for delete to authenticated
  using (bucket_id = 'media' and (public.is_editor_or_admin() or owner_id = (select auth.uid())::text));

-- ============================================================================
-- 20261001001600_cron_jobs.sql
-- ============================================================================
-- El Borj — 16 scheduled jobs (pg_cron) and optional cache revalidation (pg_net)

-- Optional: lets the database ask the site to refresh its cache right after a
-- scheduled article goes live. Fill it in with supabase/APPLY.md step 8; while it
-- is empty, pages simply refresh within 60 seconds.
create table private.app_config (
  key text primary key,
  value text not null
);
revoke all on private.app_config from public, anon, authenticated;

create or replace function public.publish_scheduled()
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  n int;
  url text;
  secret text;
begin
  update public.articles
     set status = 'published',
         published_at = scheduled_for,
         first_published_at = coalesce(first_published_at, scheduled_for),
         scheduled_for = null
   where status = 'scheduled' and scheduled_for <= now();
  get diagnostics n = row_count;

  if n > 0 then
    select value into url from private.app_config where key = 'revalidate_url';
    select value into secret from private.app_config where key = 'revalidate_secret';
    if url is not null and secret is not null then
      begin
        perform net.http_post(
          url := url,
          body := jsonb_build_object('tags', jsonb_build_array('articles')),
          headers := jsonb_build_object('Content-Type', 'application/json', 'x-revalidate-secret', secret)
        );
      exception when others then
        null; -- revalidation is best effort; time-based revalidation still applies
      end;
    end if;
  end if;
  return n;
end;
$$;

create or replace function public.expire_breaking()
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  n int;
begin
  update public.articles set is_breaking = false
   where is_breaking and breaking_until < now();
  get diagnostics n = row_count;
  return n;
end;
$$;

revoke all on function public.publish_scheduled(), public.expire_breaking() from public, anon, authenticated;
grant execute on function public.publish_scheduled(), public.expire_breaking() to service_role;

-- Schedules are in UTC. Tunisia is UTC+1 all year (no DST), so 02:15 Africa/Tunis = 01:15 UTC.
select cron.schedule('publish_scheduled', '* * * * *', $$select public.publish_scheduled()$$);
select cron.schedule('expire_breaking', '*/5 * * * *', $$select public.expire_breaking()$$);
select cron.schedule('rollup_hourly', '5 * * * *', $$select public.rollup_hourly()$$);
select cron.schedule('rollup_nightly', '15 1 * * *', $$select public.rollup_nightly()$$);
select cron.schedule('rotate_salt', '5 0 1 * *', $$select public.rotate_salt()$$);
-- Keep pg_cron's own history small on the free plan.
select cron.schedule('purge_cron_history', '30 3 * * *', $$delete from cron.job_run_details where end_time < now() - interval '7 days'$$);

-- Create this month's and next month's salt right away.
select public.rotate_salt();

-- ============================================================================
-- 20261001001700_public_views.sql
-- ============================================================================
-- El Borj — 17 read models for the public site
-- One row per article with everything a story unit needs (section, genre, cover,
-- bylines), so a page is built with very few database round trips (the Workers
-- free plan allows 50 sub-requests per request).

create or replace function public.media_json(m public.media)
returns jsonb
language sql
stable
set search_path = ''
as $$
  select case when m.id is null then null else jsonb_build_object(
    'id', m.id, 'path', m.storage_path, 'variants', m.variants, 'width', m.width, 'height', m.height,
    'focal_x', m.focal_x, 'focal_y', m.focal_y, 'alt_ar', m.alt_ar, 'alt_fr', m.alt_fr,
    'caption_ar', m.caption_ar, 'caption_fr', m.caption_fr, 'credit', m.credit, 'mime_type', m.mime_type) end;
$$;

-- One definition, two views:
-- * article_cards_all: SECURITY INVOKER, no status filter (staff, RLS applies).
-- * article_cards: published articles whose time has come; runs with the view
--   owner's rights so bylines show without exposing the profiles table to anon.
do $do$
declare
  q text := $q$
select
  a.id, a.public_id, a.language, a.translation_group_id, a.status, a.kicker_override, a.title, a.subtitle,
  a.slug, a.excerpt, a.category_id, a.format_id, a.location, a.byline_override,
  a.is_breaking, a.breaking_until, a.is_featured, a.is_sponsored, a.sponsor_name, a.allow_ads,
  a.reading_minutes, a.published_at, a.first_published_at, a.content_updated_at, a.is_demo,
  a.cover_caption, a.cover_credit, a.cover_alt,
  c.slug as category_slug, c.name_ar as category_name_ar, c.name_fr as category_name_fr,
  c.color as category_color, c.parent_id as category_parent_id,
  f.slug as format_slug, f.name_ar as format_name_ar, f.name_fr as format_name_fr,
  coalesce(f.show_as_kicker, false) as format_show_as_kicker, coalesce(f.is_opinion, false) as format_is_opinion,
  (select public.media_json(m) from public.media m where m.id = a.cover_media_id) as cover,
  coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', p.id, 'slug', p.slug, 'name_ar', p.display_name_ar, 'name_fr', p.display_name_fr,
      'title_ar', p.title_ar, 'title_fr', p.title_fr,
      'linkable', p.is_active and p.show_public_page,
      'avatar', (select public.media_json(m) from public.media m where m.id = p.avatar_media_id)
    ) order by aa.position, p.display_name_ar)
    from public.article_authors aa join public.profiles p on p.id = aa.profile_id
    where aa.article_id = a.id), '[]'::jsonb) as authors,
  coalesce((select array_agg(t.tag_id) from public.article_tags t where t.article_id = a.id), '{}'::uuid[]) as tag_ids,
  coalesce((select array_agg(x.category_id) from public.article_categories x where x.article_id = a.id), '{}'::uuid[]) as extra_category_ids
from public.articles a
join public.categories c on c.id = a.category_id
left join public.article_formats f on f.id = a.format_id
$q$;
begin
  execute 'create view public.article_cards_all with (security_invoker = true) as ' || q;
  execute 'create view public.article_cards as ' || q
       || ' where a.status = ''published'' and a.published_at <= now()';
end
$do$;

-- Author page data with the portrait.
create or replace view public.public_authors as
  select p.id, p.slug, p.display_name_ar, p.display_name_fr, p.title_ar, p.title_fr, p.bio_ar, p.bio_fr,
         p.avatar_media_id, p.email_public, p.social, p.is_demo,
         (select public.media_json(m) from public.media m where m.id = p.avatar_media_id) as avatar
  from public.profiles p
  where p.is_active and p.show_public_page;

revoke all on public.article_cards, public.article_cards_all, public.public_authors from anon, authenticated;
grant select on public.article_cards, public.public_authors to anon, authenticated;
grant select on public.article_cards_all to authenticated;

-- ============================================================================
-- 20261001001800_author_select_own_insert.sql
-- ============================================================================
-- El Borj — 18 authors can read back the article they just created
-- INSERT ... RETURNING checks the SELECT policy against the new row; the helper
-- is_article_author() reads the table and can't see that row yet, so authors' inserts
-- through the API were refused. Check created_by directly first.

drop policy articles_select on public.articles;
create policy articles_select on public.articles for select to anon, authenticated
  using (
    (status = 'published' and published_at <= now())
    or public.is_editor_or_admin()
    or (public.is_staff() and (created_by = (select auth.uid()) or public.is_article_author(id)))
  );

-- ============================================================================
-- 20261001001900_html_guard.sql
-- ============================================================================
-- El Borj — 19 stored HTML guard (defence in depth)
-- Article and page HTML is rendered from the editor JSON and sanitized on the server
-- when saved. This trigger additionally refuses dangerous markup written by any other
-- path (e.g. someone with an editor account calling the API directly), so the public
-- site can print stored HTML without re-sanitizing it on every render.

create or replace function public.html_is_safe(html text)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select html is null or not (
    html ~* '<\s*(script|style|object|embed|form|input|button|textarea|select|link|meta|base|svg|math)\y'
    or html ~* '\son[a-z]+\s*='
    or html ~* '(href|src|srcset)\s*=\s*["'']?\s*(javascript|data|vbscript):'
    or html ~* '<iframe(?![^>]*\ssrc="https://(www\.youtube-nocookie\.com|www\.facebook\.com)/)'
  );
$$;

create or replace function public.html_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not public.html_is_safe(new.body_html) then
    raise exception 'unsafe_html: body_html contains markup that is not allowed' using errcode = '22023';
  end if;
  return new;
end;
$$;

create trigger articles_html_guard before insert or update of body_html on public.articles
  for each row execute function public.html_guard();
create trigger pages_html_guard before insert or update of body_html on public.pages
  for each row execute function public.html_guard();

-- ============================================================================
-- 20261003100000_events_calendar.sql
-- ============================================================================
-- Events calendar (أجندة) and the switch that hides the French interface from readers.
--
-- An event is a dated item on the public calendar: a festival night, a protest, a match, a
-- deadline, or a public holiday. It can link to the article that announced it; the event
-- then stays hidden until that article is public. Holidays are rows like any other
-- (kind 'holiday'); Islamic holidays are added as estimates (is_estimate) from the Hijri
-- calendar and confirmed by the editor after the official announcement.

create type public.event_kind as enum ('event', 'holiday');

create table public.events (
  id uuid primary key default gen_random_uuid(),
  kind public.event_kind not null default 'event',
  title_ar text not null check (char_length(title_ar) between 1 and 300),
  title_fr text check (title_fr is null or char_length(title_fr) <= 300),
  starts_on date not null,
  ends_on date check (ends_on is null or ends_on >= starts_on),
  start_time time,
  end_time time,
  place text check (place is null or char_length(place) <= 200),
  town_tag_id uuid references public.tags (id) on delete set null,
  article_id uuid references public.articles (id) on delete set null,
  is_estimate boolean not null default false,
  is_visible boolean not null default true,
  created_by uuid references public.profiles (id) on delete set null default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.events is 'Public calendar (أجندة): events and public holidays, optionally linked to an article.';
comment on column public.events.is_estimate is 'Date not confirmed yet (Islamic holidays before the official announcement).';

create index events_starts_on_idx on public.events (starts_on);
create index events_article_idx on public.events (article_id) where article_id is not null;
create index events_town_idx on public.events (town_tag_id) where town_tag_id is not null;
create index events_created_by_idx on public.events (created_by) where created_by is not null;

create trigger events_set_updated_at
  before update on public.events
  for each row execute function public.set_updated_at();

alter table public.events enable row level security;

-- Readers: visible events whose article (if any) is public.
create policy events_select on public.events for select to anon, authenticated
  using ((is_visible and (article_id is null or public.is_article_public(article_id))) or public.is_staff());
create policy events_write on public.events for all to authenticated
  using (public.is_editor_or_admin()) with check (public.is_editor_or_admin());

-- Homepage builder: an "agenda" block (next events).
alter type public.homepage_section_type add value if not exists 'agenda';

-- Reader-facing languages. French off = no FR switch and no hreflang to /fr (the admin stays bilingual).
insert into public.site_settings (key, value, is_public)
values ('public_languages', '{"fr": false}'::jsonb, true)
on conflict (key) do nothing;

